insert into public.items (id, title, grade, domain, standard, item_type, prompt, conditions, rubric, rubric_status, rubric_source, approved_at)
values ('it-seed-fraction', '분모가 다른 분수의 크기 비교하기', '5', '수와 연산', '[6수01-07] 분모가 다른 분수의 크기를 비교할 수 있다.', '논술형', '은희와 건이는 피자를 나누어 먹기로 했습니다. 은희는 전체 피자의 1/2을 먹고, 건이는 전체 피자의 4/8를 먹기로 했습니다. 그런데 은희가 자기 피자가 더 적다며 공평하지 않다고 합니다. 분수의 크기를 비교하는 방법을 활용하여 은희의 주장에 대한 자신의 생각과 그 이유를 설명하시오.', '단, 답안은 처음-가운데-끝의 구조로 글을 쓰고, 반드시 글의 제목을 쓴다.', '{"holistic": {"상": "처음, 가운데, 끝을 나누고, 통분을 이해하고, 분모가 다른 분수의 크기를 비교하는 방법을 이해하여 글을 씀", "중": "처음, 가운데, 끝을 나누고, 통분을 이해하고, 분모가 다른 분수의 크기를 비교하는 방법을 부분적으로 이해하여 글을 씀", "하": "분수의 크기 비교 방법을 정리하여 글을 구성하려고 노력함"}, "analytic": [{"area": "과제파악", "area_score": 10, "subs": [{"name": "충실성", "interval": 5, "levels": [{"level": "상", "score": 10, "descriptor": "과제 상황을 명확히 파악하여 충실하게 해결하고 적실한 제목을 기술함"}, {"level": "중", "score": 5, "descriptor": "과제 상황을 대체로 파악하여 과제의 해결에 임함"}, {"level": "하", "score": 0, "descriptor": "과제 상황 파악이 필요함"}]}]}, {"area": "내용", "area_score": 50, "subs": [{"name": "명료성과 적실성", "interval": 10, "levels": [{"level": "상", "score": 25, "descriptor": "통분을 이해하고, 분모가 다른 분수의 크기를 비교하는 방법에 초점을 맞춰 내용을 명료하고 적실하게 제시함"}, {"level": "중", "score": 15, "descriptor": "분모가 다른 분수의 크기 비교 방법에 초점을 맞춰 내용을 제시함"}, {"level": "하", "score": 5, "descriptor": "분모가 다른 분수의 크기 비교 방법에 초점화 없이 내용을 제시함"}]}, {"name": "구체성", "interval": 10, "levels": [{"level": "상", "score": 25, "descriptor": "통분을 이해하고, 분모가 다른 분수의 크기를 비교하는 방법의 구체적인 세부 내용을 제시하여 설명함"}, {"level": "중", "score": 15, "descriptor": "분모가 다른 분수의 크기 비교 방법의 일부 내용을 설명함"}, {"level": "하", "score": 5, "descriptor": "분모가 다른 분수의 크기 비교 방법을 추상적으로만 설명함"}]}]}, {"area": "조직", "area_score": 20, "subs": [{"name": "통일성[일관성]", "interval": 5, "levels": [{"level": "상", "score": 10, "descriptor": "통분을 이해하고, 분모가 다른 분수의 크기를 비교하는 방법을 중심으로 통일성 갖춘 글을 구성함"}, {"level": "중", "score": 5, "descriptor": "통분을 이해하고, 분모가 다른 분수의 크기를 비교하는 방법을 중심으로 통일성을 갖추었으나 관련성 적은 글을 구성함"}, {"level": "하", "score": 0, "descriptor": "주제와 관련성 없는 내용을 포함하는 글을 구성함"}]}, {"name": "체계성", "interval": 5, "levels": [{"level": "상", "score": 10, "descriptor": "통분을 이해하고, 분모가 다른 분수의 크기를 비교하는 방법을 문장과 문단으로 자연스럽게 연결하여 글을 구성함"}, {"level": "중", "score": 5, "descriptor": "분모가 다른 분수의 크기를 비교하는 방법에 대해 대체로 체계적이며 문장 및 문단 간 연결성 있게 글을 구성함"}, {"level": "하", "score": 0, "descriptor": "주제와 연관성이 적은 문장과 문단으로 글을 구성함"}]}]}, {"area": "표현", "area_score": 20, "subs": [{"name": "어휘 및 문장의 적실성", "interval": 5, "levels": [{"level": "상", "score": 10, "descriptor": "주제에 대한 적확한 어휘를 선택하고 자연스러운 문장 구성함"}, {"level": "중", "score": 5, "descriptor": "어휘 선택과 문장 표현이 적실함"}, {"level": "하", "score": 0, "descriptor": "문장호응이나 어휘 선택이 어색함"}]}, {"name": "어법의 정확성", "interval": 5, "levels": [{"level": "상", "score": 10, "descriptor": "모든 문장에 어법에 맞는 맞춤법과 띄어쓰기 사용함"}, {"level": "중", "score": 5, "descriptor": "대체로 어법에 맞는 맞춤법과 띄어쓰기 사용함"}, {"level": "하", "score": 0, "descriptor": "의사전달에 오해를 유발하는 맞춤법과 띄어쓰기 사용함"}]}]}], "intent": {"purpose": "통분을 이해하고, 분모가 다른 분수의 크기를 비교하는 방법을 알고 분수의 크기를 비교할 수 있는지 평가한다.", "처음": "분모가 같은 분수의 크기 비교를 설명하고, 분모가 다를 경우에는 어떻게 해야 하는지에 대한 의문을 제시한다.", "가운데": "분모가 다른 분수의 크기를 비교하는 방법에 대한 설명이 들어가도록 한다.", "끝": "분모가 다른 분수의 크기 비교가 필요한 이유(상황)를 포함하여 글을 마무리한다."}, "model": {"title": "분모가 다른 분수의 크기 비교", "처음": "분수의 크기를 비교하는 방법은 분모가 같은 경우와 분모가 다른 경우에 각각 다르다. 분모가 같은 경우에는 분자의 크기로 분수의 크기를 비교하면 된다. 하지만 은희와 건이의 상황은 분모가 다른 분수의 크기를 비교하는 것이므로 통분이라는 과정을 거치며, 다음에서 은희의 주장이 옳지 않음을 설명할 수 있다.", "가운데": "분모가 다른 분수의 크기를 비교하려면 먼저 분모를 같은 숫자로 만들어 주어야 하는데 그것을 통분이라고 한다. 통분하기 위해서는 분수에서 분모와 분자에 0이 아닌 같은 수를 곱하거나 나누어도 그 크기에는 변함이 없다는 사실을 이용할 수 있다. 이때, 각 분모의 최소공배수를 이용하여 공통분모로 나타내면 된다. 즉, 1/2과 4/8에서 2와 8의 최소공배수인 8을 만들기 위해 1/2에는 분모와 분자에 각각 4를, 4/8에는 각각 1을 곱한다. 그러면 1/2은 4/8가 되고, 4/8은 그대로 4/8가 된다. 분모를 같게 만든 이후에는 분자의 크기 비교를 하면 되므로 1/2과 4/8의 크기는 같다고 할 수 있다. 따라서 위의 문제 상황과 같이 피자를 나누어 먹는 것이 공평하지 않다고 주장하는 은희의 의견은 옳지 않다.", "끝": "분수의 크기 비교를 할 때 분모의 숫자가 다른 분수의 크기를 비교하는 경우에는 먼저 최소공배수를 이용하여 분모를 통분하여 분자의 크기를 비교하면 된다."}}'::jsonb, 'approved', '서울교육정책연구소(2022) 부록 2 수-5-수와연산 원문', now())
on conflict (id) do nothing;

