values ('an-seed-leejuwon', 'it-seed-fraction', '이주원', '5', '4', '{}', 'reported', '{"title": "누가 더 많이 먹을까요?", "intro": "은희와 건이는 똑같이 먹었다.\n[지움: 판독 불가 — 아래 두 줄에 ''1/2'', ''4/8'', ''2, 8'' 흔적]", "body": "그이유는 은희는 1/2를먹고 건이는 4/8을 먹었는데 이 먹은 양을 분수로 바꾸게 되면 1/2과 4/8이다. 이걸 통분하면 4/8, 4/8이고 또 약분하면 1/2, 1/2 이다", "conclusion": "은희는 더 적게 먹지 않았다", "notes": "서론 아래 두 줄은 지운 흔적으로 판독 불가. 세로로 쓴 분수(4/8, 4/8 / 1/2, 1/2)는 가로 표기로 바꿈. 본론 우측 끝 ''먹었는데'', ''약분하면''이 칸 경계에 걸침.", "confidence": "medium", "read_at": "2026-09-19T01:05:00Z"}'::jsonb, '{"holistic": {"level": "중", "reason": "처음·가운데·끝을 나누고 통분과 약분으로 1/2과 4/8의 크기가 같음을 판단했으나, 통분의 원리(분모와 분자에 같은 수를 곱하거나 나눔)와 은희의 주장에 대한 판단 문장이 빠져 있어 방법을 부분적으로 이해하여 쓴 답안이다."}, "scores": [{"area": "과제파악", "sub": "충실성", "level": "상", "score": 10, "evidence": "누가 더 많이 먹을까요?", "comment": "제목을 쓰고 두 사람이 먹은 양을 비교하는 과제 상황을 정확히 파악해 해결에 임함."}, {"area": "내용", "sub": "명료성과 적실성", "level": "중", "score": 15, "evidence": "이걸 통분하면 4/8, 4/8이고 또 약분하면 1/2, 1/2 이다", "comment": "통분·약분 두 방법으로 크기가 같다는 결론에 초점을 맞췄으나, 통분을 어떻게 하는지와 은희의 주장이 옳지 않다는 판단이 명시되지 않음."}, {"area": "내용", "sub": "구체성", "level": "중", "score": 15, "evidence": "이 먹은 양을 분수로 바꾸게 되면 1/2과 4/8이다", "comment": "결과(4/8, 4/8)만 나열하고 분모·분자에 같은 수를 곱한다는 세부 과정이 없어 방법의 일부 내용만 설명함."}, {"area": "조직", "sub": "통일성[일관성]", "level": "상", "score": 10, "evidence": "은희와 건이는 똑같이 먹었다.", "comment": "서론의 주장, 본론의 이유, 결론이 모두 분수 크기 비교라는 주제 안에서 일관됨."}, {"area": "조직", "sub": "체계성", "level": "중", "score": 5, "evidence": "이 먹은 양을 분수로 바꾸게 되면 1/2과 4/8이다", "comment": "처음-가운데-끝 구조는 갖췄으나 이미 분수인 값을 다시 분수로 바꾼다는 순환 문장이 있고, 결론이 서론과 사실상 같은 문장이라 문장 간 연결이 느슨함."}, {"area": "표현", "sub": "어휘 및 문장의 적실성", "level": "중", "score": 5, "evidence": "분수로 바꾸게 되면", "comment": "''통분'', ''약분'' 등 핵심 어휘는 적절하나 ''분수로 바꾸게 되면''처럼 호응이 어색한 표현이 있음."}, {"area": "표현", "sub": "어법의 정확성", "level": "중", "score": 5, "evidence": "그이유는 은희는 1/2를먹고", "comment": "띄어쓰기 오류가 여러 곳 있으나 의사 전달에는 지장이 없음."}], "total": 65, "structure": {"title": true, "intro": true, "body": true, "conclusion": true}, "strengths": ["통분(4/8, 4/8)과 약분(1/2, 1/2) 두 가지 방법으로 두 분수가 같음을 확인해 크기가 같은 분수 개념을 정확히 알고 있음.", "결론 ''은희는 더 적게 먹지 않았다''가 문제 상황(은희의 불만)에 직접 대응함.", "제목과 처음-가운데-끝 구조를 모두 갖춤."], "weaknesses": ["통분·약분이 왜 값을 바꾸지 않는지(분모와 분자에 같은 수 곱하기·나누기)에 대한 근거 문장이 없음.", "문항이 요구한 ''은희의 주장에 대한 생각''을 ''옳지 않다/공평하다''처럼 명시하는 판단 문장이 없음.", "''먹은 양을 분수로 바꾸게 되면 1/2과 4/8이다''는 이미 분수인 값을 다시 분수로 바꾼다는 순환 문장임."], "misconceptions": [], "illegible_impact": "none", "notes": "서론의 지운 흔적은 채점에 반영하지 않음."}'::jsonb, '{"teacher": {"summary": "총점 65/100, 총체적 수준 중. 분모가 다른 분수의 크기 비교 개념은 정확하나(오개념 없음), 과정의 근거와 문항이 요구한 판단 문장을 쓰지 못해 내용·조직·표현에서 중 수준에 머묾. 개념 재교육은 불필요하고 ''아는 것을 글로 증명하는 기술'' 지도가 필요함.", "analysis": [{"type": "강점", "text": "통분과 약분 두 경로로 1/2=4/8을 검증해 동치분수 개념을 확실히 이해함(\"통분하면 4/8, 4/8이고 또 약분하면 1/2, 1/2\")."}, {"type": "강점", "text": "결론이 문제 상황에 직접 대응함(\"은희는 더 적게 먹지 않았다\"). 서론 초안을 지우고 본론으로 옮긴 흔적은 3단 구조를 의식하고 쓴다는 방증."}, {"type": "약점", "text": "절차의 근거 부재: 통분·약분이 왜 값을 바꾸지 않는지 한 문장도 없이 결과만 보고함."}, {"type": "약점", "text": "판단 문장 부재: ''은희의 주장은 옳지 않다''는 평가 문장 없이 사실만 진술함. 논술형 채점의 핵심 변별 포인트."}, {"type": "약점", "text": "순환 문장(\"분수로 바꾸게 되면 1/2과 4/8이다\")과 띄어쓰기 오류로 조직·표현에서 감점."}], "guidance": [{"title": "과정의 근거 쓰기", "what": "통분·약분의 결과만 쓰는 단계에서 ''왜 같은가''를 쓰는 단계로 올린다.", "how": "모델 문장 \"1/2의 분모와 분자에 각각 4를 곱하면 4/8이 되므로 두 분수는 크기가 같다\"를 보여준 뒤 학생이 자기 답안을 고쳐 쓰게 한다. 질문 프롬프트: \"통분하면 4/8이 된다고 했는데, 어떻게 해서 4/8이 됐어? 그걸 글로 써 보자.\""}, {"title": "문항이 묻는 것에 답하기", "what": "논술형은 사실이 아니라 주장에 대한 판단을 묻는다는 것을 명시적으로 가르친다.", "how": "문항에서 ''무엇에 대한 생각을 묻는가''를 밑줄 치게 하고, 결론 첫 문장이 그 밑줄에 답하는지 확인하는 절차를 습관화한다. 결론 템플릿: \"따라서 은희의 주장은 (옳다/옳지 않다). 왜냐하면 …\""}], "practice": [{"name": "두 문장 증명", "method": "분모가 다른 분수 한 쌍을 주고 ''통분 과정 1문장 + 비교 결과 1문장''만 쓰게 함. 계산이 아니라 문장을 채점.", "frequency": "주 3회, 2주"}, {"name": "크기가 다른 경우", "method": "1/2 vs 3/8, 2/3 vs 5/9처럼 답이 ''같지 않은'' 쌍으로 같은 훈련. 부등 상황에서도 근거 서술이 유지되는지 확인.", "frequency": "주 2회, 2주"}, {"name": "판단 문장 쓰기", "method": "''○○의 주장은 옳은가'' 형식의 짧은 논술 3문항. 결론에 판단이 있으면 통과.", "frequency": "1회"}, {"name": "자기 문장 다시 읽기", "method": "다 쓴 뒤 소리 내어 읽고 말이 되는지 표시. 순환 문장 제거 목적.", "frequency": "매 논술 후"}], "reassessment": {"prompt": "민수는 주스 한 병의 2/3를, 수아는 같은 병 크기 주스의 5/9를 마셨습니다. 수아가 자기가 더 많이 마셨다고 합니다. 수아의 말이 맞는지 판단하고, 분수의 크기를 비교하는 과정을 이유와 함께 설명하시오.", "check_points": ["동치가 아닌 쌍에서도 통분 근거(분모·분자에 같은 수 곱하기)를 쓰는가", "결론에 ''수아의 말은 맞지 않다''는 판단 문장이 있는가", "처음-가운데-끝과 제목을 갖추는가"]}}, "parent": {"summary": "이번 평가는 분모가 다른 두 분수(1/2과 4/8)의 크기를 비교하고, 그 이유를 글로 설명하는 논술형 문항이었습니다. 이주원 학생은 100점 만점에 65점으로 ''중'' 수준을 받았으며, 분수의 크기를 비교하는 개념은 정확하게 알고 있고 그 이해를 글로 설명하는 연습이 더 필요합니다.", "strengths": [{"title": "분수 비교 개념이 정확합니다.", "text": "통분(4/8, 4/8)과 약분(1/2, 1/2) 두 가지 방법을 모두 사용해 두 분수가 같다는 것을 스스로 두 번 확인했습니다. 개념을 단단히 이해하고 있다는 표시입니다."}, {"title": "문제 상황에 맞는 결론을 냈습니다.", "text": "\"은희는 더 적게 먹지 않았다\"라고 써서 계산 결과를 다시 문제의 이야기로 연결했습니다. 많은 학생이 계산만 하고 끝내는 부분입니다."}, {"title": "글의 짜임새를 지켰습니다.", "text": "제목을 붙이고 서론·본론·결론을 모두 채웠습니다. 서론에 먼저 쓴 내용을 지우고 본론으로 옮긴 흔적은 글의 구조를 생각하며 쓰고 있다는 좋은 신호입니다."}], "practice": [{"title": "\"왜 그렇게 되는지\"를 한 문장 더 쓰기", "text": "답안에는 \"통분하면 4/8\"이라는 결과만 있고, \"1/2의 분모와 분자에 각각 4를 곱하면 4/8이 된다\"는 과정이 빠져 있습니다. 머릿속에서는 하고 있는 계산을 글로 내보이는 연습이 필요합니다."}, {"title": "문제가 묻는 것에 직접 답하기", "text": "문제는 \"은희의 주장이 맞는지 생각을 써라\"고 했는데, 답안은 \"똑같이 먹었다\"는 사실까지만 썼습니다. \"그러므로 은희의 주장은 옳지 않다\"처럼 자신의 판단을 마지막에 분명히 쓰는 습관을 들이면 논술형 점수가 바로 올라갑니다."}, {"title": "쓴 글을 한 번 다시 읽기", "text": "\"먹은 양을 분수로 바꾸면 1/2과 4/8이다\"처럼 이미 분수인 값을 다시 분수로 바꾼다고 쓴 부분과 띄어쓰기 오류가 있습니다. 수학 실력의 문제가 아니라, 다 쓰고 나서 한 번만 읽어 보면 스스로 고칠 수 있는 부분입니다."}]}}'::jsonb, now(), now(), now())
on conflict (id) do nothing;
